    "questionAr": "احسب حجم متوازي السطوح القائم المحدد بالمتجهات $\\vec{u} = (2, 0, 0)$ و $\\vec{v} = (0, 2, 0)$ و $\\vec{w} = (0, 0, 3)$ في $\\mathbb{R}^3$.",
